const EXERCISES = [
 {topic:'СИГНАЛЫ',title:'01. Составьте фрагмент матрицы ТС/ТИ/ТУ',points:15,
  task:`<p><strong>Условие.</strong> На условной ПС модернизируют два выключателя 35 кВ. Для каждого нужны: положение (как одно двухточечное значение DP), «неисправность» (SP), «местный режим» (SP), три фазных тока (ТИ) и пара команд «включить/отключить» как один двухпозиционный командный объект.</p><p><strong>Сделайте:</strong> таблицу наименований и типов, подсчитайте логические объекты каждого типа. Укажите, каких исходных данных не хватает для кабельной схемы.</p>`,
  solution:`<p><strong>Ожидаемо:</strong> DP = 2; одноточечных ТС SP = 4; ТИ = 6; двухпозиционных командных объектов = 2. Это <em>логический</em> объём; количество физических каналов ввода/вывода, проводов и адресов уточняется отдельно.</p><p><strong>Нужно запросить:</strong> точные устройства-источники, наличие и схему блок-контактов, цифровые интерфейсы, карты протоколов, кто формирует команду, цепи разрешения/блокировок, требования к приёмникам, качество и временные метки.</p>`},
 {topic:'СХЕМА ОБМЕНА',title:'02. Выберите предварительные каналы связи',points:15,
  task:`<p><strong>Условие.</strong> Новая ССПИ должна передавать ТС/ТИ в ЦУС по проектируемой ВОЛС. На ПС остаётся ТМ с последовательным интерфейсом и существующий технологический канал. Заказчик дополнительно рассматривает резерв через сотовую сеть.</p><p><strong>Сделайте:</strong> блок-схему, укажите возможные протоколы, состав вопросов заказчику и меры, которые нельзя выбирать без исходных данных.</p>`,
  solution:`<p><strong>Один из допустимых вариантов:</strong> новый ПТК ↔ ЦУС по TCP/IP (IEC 104 при поддержке обеих сторон) через ВОЛС; существующая ТМ ↔ система интеграции по фактическому интерфейсу и подтверждённому протоколу; резерв через мобильную сеть — только после подтверждения требований к связи, ИБ и адресации.</p><p>Нельзя заранее утверждать, что старая ТМ использует именно IEC 101, или что новый канал уже поддерживает резервирование. Требуются паспорта, схемы связи, ТУ, формуляры и требования ЦУС.</p>`},
 {topic:'ДОКУМЕНТАЦИЯ',title:'03. Разнесите проектные результаты по документам',points:15,
  task:`<p>Распределите по логике задач: 1) требования к времени автономии; 2) концепция интеграции старой телемеханики; 3) обоснование архитектуры и отказоустойчивости; 4) схема клеммных подключений; 5) монтажная схема шкафа завода; 6) протокол проверки корректности ТС.</p><p>Объясните, почему один результат может уточняться в нескольких документах.</p>`,
  solution:`<p>Обычно: <strong>1 — ТЗ;</strong> <strong>2 — ОТР;</strong> <strong>3 — ПД;</strong> <strong>4 — РД;</strong> <strong>5 — ЗД;</strong> <strong>6 — материалы ПНР/испытаний.</strong></p><p>Границы не жёсткие: требование из ТЗ отражается в ПД, конкретизируется в РД и проверяется ПНР. Окончательный состав определяется заданием, договором и действующими требованиями.</p>`},
 {topic:'RS-485',title:'04. Проведите предварительное ревью линии RS-485',points:15,
  task:`<p>На эскизе шина RS-485 разветвлена длинной звездой, на каждом ответвлении стоят оконечные резисторы, экраны и общий провод нигде не показаны, а устройство на удалённом конце подключено без данных о допустимом синфазном напряжении.</p><p>Назовите не менее пяти проблем/вопросов и предложите план проверки.</p>`,
  solution:`<p>Проверить топологию и длину ответвлений; количество/место оконечных резисторов (как правило, на двух концах линии); необходимость смещения линии; общий потенциал/изоляцию; экранирование и заземление по документации изготовителей; место установки УЗИП; скорости, длины, тип кабеля, полярность A/B и параметры участников.</p><p>Не существует универсального правила «всегда соединить GND с PE» или «экран всегда заземлять только с одного конца»: решение зависит от оборудования, EMC, схемы заземления и условий ПС.</p>`},
 {topic:'ПИТАНИЕ',title:'05. Оцените предварительную автономию',points:15,
  task:`<p>Суммарная активная мощность потребителей шкафа в расчётном режиме — <strong>180 Вт</strong>. В ТЗ требуется автономия <strong>6 часов</strong>. Для первичной грубой оценки используйте КПД цепи резервного питания 0,85.</p><p>Сколько энергии нужно потребителям, сколько ориентировочно требуется на стороне запаса энергии и почему это ещё не готовый выбор аккумуляторов?</p>`,
  solution:`<p>Энергия нагрузки: <strong>180 × 6 = 1080 Вт·ч = 1,08 кВт·ч</strong>. Грубая оценка от источника: <strong>1080 / 0,85 ≈ 1271 Вт·ч</strong> (1,27 кВт·ч).</p><p>Это лишь оценка. Для выбора ИБП/АКБ нужны DC-шина и рабочий диапазон напряжений, допустимая глубина разряда, температура, старение, пусковые токи, резерв на развитие, кривая разряда, режимы работы, зарядное устройство, политика резервирования и фактический паспорт.</p>`},
 {topic:'НОРМОКОНТРОЛЬ',title:'06. Найдите противоречия в комплекте РД',points:25,
  task:`<p>В учебном комплекте: в ТЗ указано два выключателя, а в спецификации только один контроллер без подтверждённого объёма точек; в таблице есть «В 35 Т‑1 Неисправность», но источник не указан; один и тот же объект в схеме назван «В35T1», а в таблице «В 35 Т‑1»; на структурной схеме предусмотрен резервный канал, но в спецификации нет его оборудования; управление выключателем показано без условий разрешения.</p><p>Составьте ведомость замечаний с приоритетом и способом закрытия каждого.</p>`,
  solution:`<p><strong>Критично:</strong> не определены разрешения и блокировки ТУ; отсутствует подтверждённая достаточность состава контроллера и его интерфейсов; резерв показан только на схеме. <strong>Существенно:</strong> нет источника ТС; разные обозначения одного объекта.</p><p>Каждое замечание закрывается согласованным исходным документом/проверенной спецификацией/обновлёнными схемами. Количество контроллеров само по себе не обязано равняться числу выключателей — требуется проверка архитектуры и ёмкости.</p>`}
];
